#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll MOD = 1000000007LL;
const ll T = 1000000000LL;

struct Line {
    ll m, c;
};

ll modpow(ll a, ll e) {
    ll res = 1;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

ll inv(ll a) {
    return modpow(a, MOD - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll N, M, K;
    cin >> N >> M >> K;

    vector<ll> a_spell(N), b_spell(N);
    for (int i = 0; i < N; ++i) cin >> a_spell[i];
    for (int i = 0; i < N; ++i) cin >> b_spell[i];

    vector<ll> a_meal(M), b_meal(M);
    for (int i = 0; i < M; ++i) cin >> a_meal[i];
    for (int i = 0; i < M; ++i) cin >> b_meal[i];

    ll Q;
    cin >> Q;
    vector<ll> queries(Q);
    for (int i = 0; i < Q; ++i) cin >> queries[i];

    // Maximum slope and corresponding intercept for spells
    ll A_spell = 0, B_spell = 0;
    for (int i = 0; i < N; ++i) {
        if (a_spell[i] > A_spell) {
            A_spell = a_spell[i];
            B_spell = b_spell[i];
        } else if (a_spell[i] == A_spell) {
            if (b_spell[i] > B_spell) B_spell = b_spell[i];
        }
    }

    ll Bmax_1 = 0;
    if (A_spell == 1) {
        for (int i = 0; i < N; ++i) Bmax_1 = max(Bmax_1, b_spell[i]);
    }

    // Convex Hull Trick for spells (only needed if max slope > 1)
    vector<Line> hull;
    vector<ll> start;

    if (A_spell > 1) {
        vector<pair<ll, ll>> lines;
        for (int i = 0; i < N; ++i) lines.push_back({a_spell[i], b_spell[i]});
        sort(lines.begin(), lines.end());

        vector<pair<ll, ll>> unique;
        for (auto &p : lines) {
            if (unique.empty() || unique.back().first != p.first) {
                unique.push_back(p);
            } else {
                if (p.second > unique.back().second) unique.back().second = p.second;
            }
        }

        for (auto &p : unique) {
            Line nl = {p.first, p.second};
            bool added = false;
            while (!hull.empty()) {
                Line last = hull.back();
                ll den = nl.m - last.m;
                ll num = last.c - nl.c;
                ll x;
                if (num <= 0) x = 0;
                else x = (num + den - 1) / den;

                if (x <= start.back()) {
                    hull.pop_back();
                    start.pop_back();
                } else {
                    start.push_back(x);
                    hull.push_back(nl);
                    added = true;
                    break;
                }
            }
            if (!added) {
                start.push_back(0);
                hull.push_back(nl);
            }
        }
    }

    auto query_max = [&](ll x) -> ll {
        int idx = upper_bound(start.begin(), start.end(), x) - start.begin() - 1;
        return hull[idx].m * x + hull[idx].c;
    };

    // Meals
    ll sum_b_1 = 0;
    vector<pair<ll, ll>> meals;
    for (int i = 0; i < M; ++i) {
        if (a_meal[i] == 1) {
            sum_b_1 = (sum_b_1 + b_meal[i]) % MOD;
        } else {
            meals.push_back({a_meal[i], b_meal[i]});
        }
    }

    sort(meals.begin(), meals.end(), [](const pair<ll, ll>& x, const pair<ll, ll>& y) {
        return (__int128)x.second * (y.first - 1) > (__int128)y.second * (x.first - 1);
    });

    ll A_meal = 1, B_meal = sum_b_1;
    for (auto &p : meals) {
        ll a = p.first % MOD;
        ll b = p.second % MOD;
        B_meal = (a * B_meal + b) % MOD;
        A_meal = (A_meal * a) % MOD;
    }

    ll inv_A_minus_1 = 0;
    if (A_spell > 1) {
        inv_A_minus_1 = inv(A_spell - 1);
    }

    for (ll x : queries) {
        ll S_mod;

        if (A_spell == 1) {
            S_mod = (x % MOD + (K % MOD) * (Bmax_1 % MOD)) % MOD;
        } else {
            ll cur = x;
            ll steps = 0;

            while (steps < K && cur < T) {
                cur = query_max(cur);
                ++steps;
            }

            if (steps == K) {
                S_mod = cur % MOD;
            } else {
                ll t = K - steps;
                ll y_mod = cur % MOD;
                ll powA = modpow(A_spell % MOD, t);
                ll term1 = powA * y_mod % MOD;
                ll geom = (powA - 1 + MOD) % MOD * inv_A_minus_1 % MOD;
                ll term2 = (B_spell % MOD) * geom % MOD;
                S_mod = (term1 + term2) % MOD;
            }
        }

        ll ans = (A_meal * S_mod + B_meal) % MOD;
        cout << ans << '\n';
    }

    return 0;
}
